#include <stdio.h>
#include <string.h>

enum nslSpeakerModeEnum { NSL_SPEAKER_STEREO };
enum nslOutputModeEnum { NSL_OUTPUT_ANALOG, NSL_OUTPUT_DIGITAL, NSL_OUTPUT_BOTH };
enum nslLanguageEnum { NSL_LANGUAGE_ENGLISH };
enum nslPs2CdDvdMode { NSL_PS2_CD_MODE };
enum _nslClearBehaviour { NSL_CLEAR_INIT };

struct nslSystem {
    char padding[0x1584c];
    int firstInit, initialized, numBanks;
    char padding2[12];
    int speakerMode, outputMode, language, cdDvdMode;
    char padding3[12];
    int on, proview, finalizeSourcesEnabled;
    float sfxVolume, ambientVolume, musicVolume, voiceVolume;
    float user1Volume, user2Volume, masterVolume, movieVolume;
    char rootDir[1];
};

extern nslSystem nsl;
extern char modDir[], gasName[];
int sceCdSync(int);
bool _nslLoadModule(char *);
void nslPs2GasRpcInit();
int nslPs2GasRpc(int, const char *, int, int, int, int);
void _nslReleaseAllSources();
void _nslResetInternal(_nslClearBehaviour);

__asm__(".equ nsl, 0x0049B5F0");
__asm__(".equ modDir, 0x004A0EC8");
__asm__(".equ gasName, 0x004A0F08");
__asm__(".equ sceCdSync, 0x003BD1C0");
__asm__(".equ _nslLoadModule__FPc, 0x003914D0");
__asm__(".equ nslPs2GasRpcInit__Fv, 0x00391A68");
__asm__(".equ nslPs2GasRpc__FiPCciiii, 0x00391AC0");
__asm__(".equ _nslReleaseAllSources__Fv, 0x0038C3A8");
__asm__(".equ _nslResetInternal__F18_nslClearBehaviour, 0x00390DA8");

bool nslInit()
{
  if (nsl.initialized) return true;

  sceCdSync(0);
  if (nsl.firstInit)
  {
    char filename[256];

    strcpy(filename,modDir);
    strcat(filename,"LIBSD.IRX");
    if (!_nslLoadModule(filename))
      return false;
    if (!_nslLoadModule("SDRDRV.IRX"))
      return false;
    strcpy(filename,modDir);
    strcat(filename,gasName);
    if (!_nslLoadModule(filename))
      return false;

    nsl.firstInit = 0;
  }
  nsl.on = false;
  nsl.initialized = 1;
  nslPs2GasRpcInit();

  nslPs2GasRpc(0x1001, "", 0, (nsl.proview?1:0), (int)nsl.cdDvdMode, 0);
  fflush(stdout);
  _nslReleaseAllSources();
  _nslResetInternal(NSL_CLEAR_INIT);

  nsl.numBanks = 0;
  nsl.finalizeSourcesEnabled = true;
  nsl.rootDir[0] = '\0';

  nsl.speakerMode = NSL_SPEAKER_STEREO;
  nsl.outputMode = NSL_OUTPUT_BOTH;
  nsl.language = NSL_LANGUAGE_ENGLISH;

  nsl.sfxVolume = 1.0f;
  nsl.ambientVolume = 1.0f;
  nsl.musicVolume = 1.0f;
  nsl.voiceVolume = 1.0f;
  nsl.masterVolume = 1.0f;
  nsl.movieVolume = 1.0f;
  nsl.user1Volume = 1.0f;
  nsl.user2Volume = 1.0f;

  return true;
}
